//go:build linux
// Standalone application-owned raw-cache lifecycle caller. Never starts AO.
package main
import("context";"encoding/json";"flag";"fmt";"os";"os/signal";"path/filepath";"syscall";"time";aosqlite "github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite";"github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite/store")
func main(){os.Exit(run())}
func run()int{
 var dir,lock,report,cut,freeze,stage string;var dev,ino uint64;var maxID int64;var rows,cacheMiB int;var cursor string;var retention,wall,batch time.Duration
 flag.StringVar(&stage,"stage","cache:raw","cache:raw, gc:activity or gc:audit");flag.StringVar(&dir,"data-dir","","existing stopped AO state");flag.StringVar(&lock,"maintenance-lock","","existing AO maintenance lock");flag.StringVar(&report,"report","","private progress JSON");flag.Uint64Var(&dev,"database-device",0,"expected device");flag.Uint64Var(&ino,"database-inode",0,"expected inode");flag.Int64Var(&maxID,"backup-max-event-id",0,"covered provider append prefix");flag.StringVar(&freeze,"backup-frozen-at","","verified backup freeze");flag.StringVar(&cut,"cutoff","","fixed raw cache cutoff");flag.DurationVar(&retention,"raw-cache-retention",6*time.Hour,"independent duplicate cache lifetime; canonical history unchanged");flag.DurationVar(&wall,"wall-budget",2*time.Hour,"total budget");flag.DurationVar(&batch,"batch-budget",30*time.Second,"each read/write budget");flag.IntVar(&cacheMiB,"cache-mib",128,"offline writer connection page cache MiB");flag.IntVar(&rows,"batch-rows",500,"bounded primary-key prefix");flag.StringVar(&cursor,"start-cursor","","last confirmed PK cursor");flag.Parse()
 if stage!="cache:raw"&&stage!="gc:activity"&&stage!="gc:audit"{return fail("invalid_stage")}
 cutoff,e:=time.Parse(time.RFC3339Nano,cut);if e!=nil{return fail("invalid_cutoff")};frozen,e:=time.Parse(time.RFC3339Nano,freeze);if e!=nil||dev==0||ino==0||maxID<=0||cacheMiB<1||cacheMiB>1024||rows<=0||rows>1000||retention<=0||retention>48*time.Hour||wall<=0||batch<=0||cutoff.After(time.Now().UTC().Add(-retention))||frozen.After(time.Now().UTC()){return fail("invalid_options")}
 if stage!="cache:raw"&&cutoff.After(time.Now().UTC().Add(-48*time.Hour)){return fail("gc_cutoff_too_recent")}
 parent,e:=os.Stat(filepath.Dir(report));if e!=nil||!parent.IsDir()||parent.Mode().Perm()!=0700||parent.Sys().(*syscall.Stat_t).Uid!=uint32(os.Getuid()){return fail("unsafe_report_parent")}
 lf,e:=os.OpenFile(lock,os.O_RDWR,0600);if e!=nil{return fail("missing_maintenance_lock")};defer lf.Close();if syscall.Flock(int(lf.Fd()),syscall.LOCK_EX|syscall.LOCK_NB)!=nil{return fail("maintenance_busy")}
 ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGTERM,syscall.SIGINT);defer stop();ctx,cancel:=context.WithTimeout(ctx,wall);defer cancel();s,e:=aosqlite.OpenHistoryGCExisting(ctx,dir,dev,ino,true,cacheMiB);if e!=nil{return fail("open_existing_failed")};defer s.Close()
 state:=map[string]any{"status":"running","stage":stage,"cutoff":cut,"retention_seconds":retention.Seconds(),"offline_writer_cache_mib":cacheMiB,"backup_max_event_id":maxID,"backup_frozen_at":freeze,"confirmed_cursor":cursor,"scanned":0,"compacted":0,"audit_deleted":0,"deleted":0,"logical_payload_bytes_removed":int64(0),"retained":map[string]int{}}
 save:=func()error{state["at"]=time.Now().UTC().Format(time.RFC3339Nano);if f,x:=os.Stat(filepath.Join(dir,"ao.db"));x==nil{state["main_file_bytes"]=f.Size()};if f,x:=os.Stat(filepath.Join(dir,"ao.db-wal"));x==nil{state["wal_file_bytes"]=f.Size()}else{state["wal_file_bytes"]=int64(0)};data,x:=json.MarshalIndent(state,"","  ");if x!=nil{return x};fd,x:=os.OpenFile(report+".new",os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if x!=nil{return x};_,x=fd.Write(data);if x==nil{x=fd.Sync()};fd.Close();if x!=nil{return x};return os.Rename(report+".new",report)}
 if e=save();e!=nil{return fail("report_write_failed")};o:=store.DefaultHistoryMaintenanceOptions();o.Retention=48*time.Hour;o.RawCacheRetention=retention;o.BatchRows=rows;o.RawCacheBatchRows=rows;o.GCBatchRows=rows;o.ReadBudget=batch;o.WriteBudget=batch;o.BatchBytes=16<<20;o.MaxRowBytes=8<<20
 for{req:=store.HistoryMaintenanceRequest{Stage:stage,Cursor:cursor,Cutoff:cutoff.Format(time.RFC3339Nano),DatabaseDevice:dev,DatabaseInode:ino,OfflineCoverageBefore:frozen,OfflineMaxEventID:maxID};bc,done:=context.WithTimeout(ctx,2*batch);r,x:=s.MaintainHistorySnapshotBatch(bc,req,o,time.Now().UTC());done()
  if x!=nil{state["status"]="failed";state["failed_phase"]=r.Phase;state["commit_state"]=r.CommitState;state["error_type"]=r.ErrorType;state["sqlite_code"]=r.SQLiteCode;save();return fail("raw_cache_batch_failed")};if r.Status=="deferred"{state["status"]="partial";state["stop_reason"]="writer_deferred";save();return 0}
  cursor=r.NextCursor;state["confirmed_cursor"]=cursor;state["scanned"]=state["scanned"].(int)+r.Scanned;state["compacted"]=state["compacted"].(int)+r.Compacted;state["audit_deleted"]=state["audit_deleted"].(int)+r.AuditDeleted;state["deleted"]=state["deleted"].(int)+r.Deleted;state["logical_payload_bytes_removed"]=state["logical_payload_bytes_removed"].(int64)+r.LogicalBytes;state["last_read_ms"]=r.ReadMS;state["last_held_ms"]=r.HeldMS;state["commit_state"]=r.CommitState;for k,v:=range r.Retained{state["retained"].(map[string]int)[k]+=v};if e=save();e!=nil{return fail("report_write_failed")}
  if r.Compacted>0||r.AuditDeleted>0||r.Deleted>0{cc,end:=context.WithTimeout(ctx,batch);_,_,_,x=s.CheckpointHistoryGC(cc);end();if x!=nil{state["status"]="failed";state["failed_phase"]="checkpoint";state["commit_state"]="committed";save();return fail("checkpoint_failed")}}
  if r.Complete{state["status"]="complete";state["scan_complete"]=true;save();fmt.Printf("{\"status\":\"complete\",\"compacted\":%d}\n",state["compacted"]);return 0}
 }
}
func fail(code string)int{v,_:=json.Marshal(map[string]string{"status":"failed","error":code});fmt.Println(string(v));return 1}
